sys_ui_action.script:
var mc = new MiniCrossword();

gs.info('Starting puzzle generation...');

var result = mc.generatePuzzle(null, 'random', null);

gs.info('=== RESULT ===');
gs.info('Success: ' + result.success);
gs.info('Message: ' + result.message);
gs.info('Puzzle Sys ID: ' + result.puzzleSysId);
gs.info('Word Count: ' + result.wordCount);
gs.info('Grid Coverage: ' + result.gridCoverage);
gs.info('Attempts Used: ' + result.attemptsUsed);

// If successful, check if records were created
if (result.success && result.puzzleSysId) {
    var puzzleGR = new
    GlideRecord('x_1468549_mini_c_0_daily_puzzle');
    if (puzzleGR.get(result.puzzleSysId)) {
        gs.info('✓ Daily puzzle record EXISTS: ' +
            puzzleGR.getDisplayValue());

        // Check grid records
        var gridGR = new
        GlideRecord('x_1468549_mini_c_0_puzzle_grid');
        gridGR.addQuery('daily_puzzle', result.puzzleSysId);
        gridGR.query();
        gs.info('✓ Puzzle grid records count: ' +
            gridGR.getRowCount());

        while (gridGR.next()) {
            gs.info('  Grid entry: word=' + gridGR.word.word +
                ', row=' + gridGR.getValue('row') + ', col=' +
                gridGR.getValue('column') + ', dir=' +
                gridGR.getValue('direction'));
        }
    } else {
        gs.error('✗ Daily puzzle record NOT FOUND with sys_id: ' +
            result.puzzleSysId);
    }
}
